def cronnext_stamps(case, expr):
    """cronnext's local wall clock firings over this case's window."""
    lo, hi = case["lo"], case["hi"]
    start = datetime.fromtimestamp(lo, timezone.utc)
    found = next_after(expr, start, 400, tz=case["zone"])
    return [
        moment.strftime("%m-%d %H:%M") + moment.strftime("%z")
        for moment in found
        if lo < int(moment.timestamp()) <= hi
    ]


def stamps_of(entry):
    """The UTC offsets cronnext reported, without the local wall clock part.

    A stamp is ``MM-DD HH:MM+HHMM``, so the offset starts at index 11.  That
    index was written out literally first and silently sliced wrong -- the
    offset assertions passed vacuously -- so it is spelled out here once.
    """
    return sorted(stamp[OFFSET_AT:] for stamp in entry["cronnext_stamps"])


class TestAmbiguousHourIsReportedAtFoldZero(unittest.TestCase):
    """The exact offset of the reported instant matters, not just the count.

    An earlier version of this file stored only the difference between the two
    sides.  That cannot tell fold=0 from fold=1: the number of firings is
    identical, and the instant is absent from vixie's list either way, so a
    mutant that reported the other offset sailed through.  A mutation check
    found it, which is why the exact stamps are pinned here.
    """

    def test_berlin_reports_the_summer_offset(self):
        case = next(
            c for c in VIXIE_FIRINGS
            if c["zone"] == "Europe/Berlin" and c["shift_minutes"] == -60
        )
        expected = case["expected"]["30 2 * * *"]
        # vixie fires twice, at +0200 and at +0100; cronnext fires once, at
        # the first pass through the clock.
        self.assertEqual(expected["vixie_count"], 2)
        self.assertEqual(expected["cronnext_stamps"], ["10-27 02:30+0200"])
        self.assertEqual(stamps_of(expected), ["+0200"])

    def test_fold_zero_is_reported_for_every_ambiguous_case(self):
        """For each ambiguous wall clock time, the FIRST pass is the one kept.

        Compared per wall clock time rather than per offset: a schedule like
        ``* * * * *`` legitimately reports +0100 for every ordinary hour in the
        window, so the assertion has to ask what happened to the specific
        repeated minute, not which offset appears in the output.
        """
        seen = 0
        for case in VIXIE_FIRINGS:
            if case["shift_minutes"] >= 0:
                continue
            for expr in EXPRESSIONS:
                entry = case["expected"][expr]
                if not entry["missing"]:
                    continue
                kept = entry["cronnext_stamps"]
                for gone in entry["missing"]:
                    wall = gone[:CLOCK_END]
                    dropped_offset = gone[OFFSET_AT:]
                    same_wall = [
                        stamp for stamp in kept if stamp[:CLOCK_END] == wall
                    ]
                    seen += 1
                    if not same_wall:
                        # The schedule does not fire at that local time at
                        # all, so there is no choice to get wrong.
                        continue
                    for stamp in same_wall:
                        self.assertNotEqual(
                            stamp[OFFSET_AT:], dropped_offset,
                            f"{case['zone']} {expr!r} kept {stamp}, the second "
                            f"pass of the fold, instead of the first pass "
                            f"over {wall}",
                        )
        self.assertGreater(seen, 0, "no ambiguous case in the fixture")

    def test_first_pass_beat_second_pass(self):
        """Every ambiguous local time is reported exactly once, never twice."""
        for case in VIXIE_FIRINGS:
            if case["shift_minutes"] >= 0:
                continue
            for expr in EXPRESSIONS:
                entry = case["expected"][expr]
                if not entry["missing"]:
                    continue
                walls = [stamp[:CLOCK_END] for stamp in entry["cronnext_stamps"]]
                self.assertEqual(
                    len(walls), len(set(walls)),
                    f"{case['zone']} {expr!r} reported a local time twice",
                )


class TestGapAgreesWithVixie(unittest.TestCase):
    """A spring forward gap must match vixie exactly.

    cronnext skips local times that do not exist, and so does vixie, because
    localtime() never reports a wall clock time inside the gap.  These are
    equal firing sets, not merely equal counts.
    """

    def gaps(self):
        return [c for c in VIXIE_FIRINGS if c["shift_minutes"] > 0]

    def test_fixture_contains_gaps(self):
        self.assertGreaterEqual(len(self.gaps()), 3)

    def test_gap_cases_agree_occurrence_for_occurrence(self):
        """The strong form: at a gap the two firing sets are identical."""
        cases = self.gaps()
        self.assertGreaterEqual(len(cases), 3)
        for case in cases:
            for expr in EXPRESSIONS:
                expected = case["expected"][expr]
                self.assertEqual(
                    expected["missing"], [],
                    f"{case['zone']} {case['note']} {expr!r}",
                )
                self.assertEqual(
                    expected["invented"], [],
                    f"{case['zone']} {case['note']} {expr!r}",
                )
                self.assertEqual(
                    expected["cronnext_stamps"],
                    cronnext_stamps(case, expr),
                    f"{case['zone']} {case['note']} {expr!r}",
                )
                self.assertEqual(
                    expected["vixie_count"], len(expected["cronnext_stamps"]),
                    f"{case['zone']} {case['note']} {expr!r}",
                )

    def test_whole_day_gap_is_handled(self):
        # Pacific/Apia did not shift its clocks on 2011-12-30, it skipped the
        # day: a 1440 minute change, far wider than a wall clock scheduler
        # normally meets, against next.py's cap of 64 attempts per result.
        case = next(c for c in self.gaps() if c["shift_minutes"] == 1440)
        self.assertEqual(case["zone"], "Pacific/Apia")
        for expr in EXPRESSIONS:
            expected = case["expected"][expr]
            self.assertEqual(expected["missing"], [], expr)
            self.assertEqual(expected["invented"], [], expr)
            self.assertEqual(
                expected["vixie_count"], expected["cronnext_count"], expr
            )


class TestFoldDivergesFromVixie(unittest.TestCase):
    """The repeated hour is where cronnext and upstream vixie part company.

    These are not expected failures.  They pin the size and shape of a
    divergence the README documents, so a change to the search that
    accidentally alters it gets noticed.
    """

    def folds(self):
        return [c for c in VIXIE_FIRINGS if c["shift_minutes"] < 0]

    def test_fixture_contains_folds(self):
        self.assertGreaterEqual(len(self.folds()), 3)

    def test_cronnext_never_invents_a_firing(self):
        for case in self.folds():
            for expr in EXPRESSIONS:
                self.assertEqual(
                    case["expected"][expr]["invented"], [],
                    f"{case['zone']} {case['note']} {expr!r}",
                )

    def test_every_dropped_firing_is_inside_the_repeated_hour(self):
        """cronnext only ever loses the second pass through the fold."""
        dropped = 0
        for case in self.folds():
            change_clock = case["change"][CLOCK_AT:CLOCK_END]
            for expr in EXPRESSIONS:
                for stamp in case["expected"][expr]["missing"]:
                    dropped += 1
                    self.assertGreaterEqual(
                        stamp[CLOCK_AT:CLOCK_END], change_clock,
                        f"{case['zone']} {expr!r} lost {stamp}, before the "
                        f"transition at {change_clock}",
                    )
        self.assertGreater(dropped, 0, "fixture has no fold divergence")

    def test_counts_and_losses_are_consistent(self):
        for case in self.folds():
            for expr in EXPRESSIONS:
                expected = case["expected"][expr]
                self.assertLessEqual(
                    expected["cronnext_count"], expected["vixie_count"],
                    f"{case['zone']} {expr!r}",
                )
                self.assertEqual(
                    expected["vixie_count"] - expected["cronnext_count"],
                    len(expected["missing"]),
                    f"{case['zone']} {expr!r}",
                )

    def test_live_stamps_still_match_the_capture(self):
        """Re-run cronnext against every frozen window and diff the result."""
        checked = 0
        for case in VIXIE_FIRINGS:
            for expr in EXPRESSIONS:
                self.assertEqual(
                    case["expected"][expr]["cronnext_stamps"],
                    cronnext_stamps(case, expr),
                    f"{case['zone']} {case['note']} {expr!r}",
                )
                checked += 1
        self.assertGreater(checked, 0)

    def test_half_hour_fold_is_covered(self):
        # Australia/Lord_Howe repeats only 30 minutes, so the ambiguous span
        # is not aligned to the hour at all.
        case = next(
            c for c in self.folds() if c["zone"] == "Australia/Lord_Howe"
        )
        self.assertEqual(case["shift_minutes"], -30)
        for expr in EXPRESSIONS:
            self.assertEqual(case["expected"][expr]["invented"], [], expr)


class TestControlZoneHasNoTransitions(unittest.TestCase):
    """UTC has nothing to decide, and must agree anyway."""

    def test_utc_window_is_identical(self):
        case = next(c for c in VIXIE_FIRINGS if c["zone"] == "UTC")
        self.assertEqual(case["shift_minutes"], 0)
        for expr in EXPRESSIONS:
            expected = case["expected"][expr]
            self.assertEqual(expected["missing"], [], expr)
            self.assertEqual(expected["invented"], [], expr)
            self.assertEqual(
                expected["vixie_count"], expected["cronnext_count"], expr
            )
